JSON.parse('{"id": 9007199254740993}');  // → 9007199254740992 (정밀도 손실!)
//   큰 정수(64bit id·금액)는 문자열로: {"id": "9007199254740993"}

JSON.stringify({ a: undefined, b: () => {} });  // → "{}" (사라짐)
//   undefined·함수·NaN·Infinity 는 표현 못 함

// 날짜: JSON 에 타입 없음 → ISO 8601 문자열로
{ "createdAt": "2026-08-12T09:30:00+09:00" }
// 금액: 부동소수 대신 정수(최소 단위)나 문자열

import { z } from 'zod';
const Item = z.object({
  id: z.string(),
  price: z.number().int().nonnegative(),
  createdAt: z.string().datetime(),   // ISO 8601
});
type Item = z.infer<typeof Item>;     // 스키마에서 타입 자동 도출

const item = Item.parse(input);       // 모양 다르면 여기서 즉시 실패
// 「나중에 터지는 것」보다 경계에서 즉시 실패가 훨씬 싸다
// 스키마 = 검증 + 타입 + 문서 (한 소스)
